a.inference.argument.splice(0,1,{...s,text:norm,uses:[],produces:[s.produces[0]]},{...s,id:"S004",text:existence,produces:[s.produces[1]],objects:[]});
store("repaired_artifact",a);text(await tools.check_draft({artifact:a}));

