const a=load("repaired_artifact");const fact=a.inference.argument[3].produces[0];
fact.statement="There exists eps with 0<eps<=1/8 such that the following inequalities hold. For each beta in [-1/2-eps,3/2] there is C3 depending only on beta and eps such that, for every tau_s>0, nonnegative integer j, t in [j*tau_s,(j+1)*tau_s] and time-independent mean-zero g1,g2 in Hsrc^(1/2), ||(1/2) integral_(j*tau_s)^t S_(-s) partial_x[(S_s g1)(S_s g2)] ds||_(Hsrc^beta)<=C3*tau_s^((3/2-beta)/(2+eps))*||g1||_(Hsrc^(1/2))*||g2||_(Hsrc^(1/2)). There is also C4 depending only on eps such that, for every p in Hsrc^(1/2) and q in Hsrc^eps, ||p*q||_(L2src)<=C4*||p||_(Hsrc^(1/2))*||q||_(Hsrc^eps). The eps and constants are independent of the functions, grid indices, times, step sizes and support.";
